DELIMITER //
CREATE PROCEDURE nightcap_thj_behavior_rule()
BEGIN
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
 SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
 START TRANSACTION;
 IF (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='rule_values' AND ENGINE='InnoDB')<>1 OR EXISTS (SELECT 1 FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND EVENT_OBJECT_TABLE='rule_values') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unexpected WPM content storage'; END IF;
 IF NOT ((SELECT COUNT(*) FROM rule_values WHERE `ruleset_id` <=> 1 AND BINARY `rule_name` <=> BINARY CONVERT(X'5370656c6c733a4e6967687463617054484a4265686176696f7273' USING utf8mb4))=1 AND NOT EXISTS (SELECT 1 FROM rule_values WHERE `ruleset_id` <=> 1 AND BINARY `rule_name` <=> BINARY CONVERT(X'5370656c6c733a4e6967687463617054484a4265686176696f7273' USING utf8mb4) AND NOT ((`ruleset_id` <=> 1 AND BINARY `rule_name` <=> BINARY CONVERT(X'5370656c6c733a4e6967687463617054484a4265686176696f7273' USING utf8mb4) AND BINARY `rule_value` <=> BINARY CONVERT(X'66616c7365' USING utf8mb4) AND BINARY `notes` <=> BINARY CONVERT(X'54484a206265686176696f722063616e6469646174653b2070616972656420776f726c642f7a6f6e652c20636f6e74656e7420616e6420636c69656e74207265717569726564' USING utf8mb4))))) THEN
  IF NOT ((SELECT COUNT(*) FROM rule_values WHERE `ruleset_id` <=> 1 AND BINARY `rule_name` <=> BINARY CONVERT(X'5370656c6c733a4e6967687463617054484a4265686176696f7273' USING utf8mb4))=1 AND NOT EXISTS (SELECT 1 FROM rule_values WHERE `ruleset_id` <=> 1 AND BINARY `rule_name` <=> BINARY CONVERT(X'5370656c6c733a4e6967687463617054484a4265686176696f7273' USING utf8mb4) AND NOT ((`ruleset_id` <=> 1 AND BINARY `rule_name` <=> BINARY CONVERT(X'5370656c6c733a4e6967687463617054484a4265686176696f7273' USING utf8mb4) AND BINARY `rule_value` <=> BINARY CONVERT(X'74727565' USING utf8mb4) AND BINARY `notes` <=> BINARY CONVERT(X'54484a206265686176696f722063616e6469646174653b2070616972656420776f726c642f7a6f6e652c20636f6e74656e7420616e6420636c69656e74207265717569726564' USING utf8mb4))))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='WPM rule_values preimage drift'; END IF;
  UPDATE rule_values SET `rule_value`=CONVERT(X'66616c7365' USING utf8mb4) WHERE `ruleset_id` <=> 1 AND BINARY `rule_name` <=> BINARY CONVERT(X'5370656c6c733a4e6967687463617054484a4265686176696f7273' USING utf8mb4);
  IF NOT ((SELECT COUNT(*) FROM rule_values WHERE `ruleset_id` <=> 1 AND BINARY `rule_name` <=> BINARY CONVERT(X'5370656c6c733a4e6967687463617054484a4265686176696f7273' USING utf8mb4))=1 AND NOT EXISTS (SELECT 1 FROM rule_values WHERE `ruleset_id` <=> 1 AND BINARY `rule_name` <=> BINARY CONVERT(X'5370656c6c733a4e6967687463617054484a4265686176696f7273' USING utf8mb4) AND NOT ((`ruleset_id` <=> 1 AND BINARY `rule_name` <=> BINARY CONVERT(X'5370656c6c733a4e6967687463617054484a4265686176696f7273' USING utf8mb4) AND BINARY `rule_value` <=> BINARY CONVERT(X'66616c7365' USING utf8mb4) AND BINARY `notes` <=> BINARY CONVERT(X'54484a206265686176696f722063616e6469646174653b2070616972656420776f726c642f7a6f6e652c20636f6e74656e7420616e6420636c69656e74207265717569726564' USING utf8mb4))))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='WPM rule_values afterimage mismatch'; END IF;
 END IF;
 COMMIT;
END//
DELIMITER ;
CALL nightcap_thj_behavior_rule();
DROP PROCEDURE nightcap_thj_behavior_rule;
